module ring_gear() {
  eps = 0.1;
  linear_extrude(height=half_h+eps, twist=-tw_ring*(half_h+eps)/half_h, slices=12, convexity=10)
    difference() {
      circle(r=30, $fn=128);
      polygon(gear_outline(Zr, Rp_ring, Rb_ring, Rt_ring, Rr_ring, thick_tooth, flank_steps));
    }
  translate([0,0,half_h-eps]) rotate([0,0,-tw_ring*(half_h-eps)/half_h])
    linear_extrude(height=half_h+eps, twist=tw_ring*(half_h+eps)/half_h, slices=12, convexity=10)
      difference() {
        circle(r=30, $fn=128);
        polygon(gear_outline(Zr, Rp_ring, Rb_ring, Rt_ring, Rr_ring, thick_tooth, flank_steps));
      }
}

